                i = cptr.ldI32o2(svb, NHC.FOOD_CLASS, 4, $instance_globals_saved_b_bases);
                cptr.ld1so2(objects, i, $sizeof_objclass, $objclass_oc_class) == NHC.FOOD_CLASS;
                i++
