                void cptr.strcpy(cptr.add(svp, $instance_globals_saved_p_pl_fruit), __s_candied);
                (yield* nmcpy(cptr.add(svp, $instance_globals_saved_p_pl_fruit + 8), cptr.decay(buf), 24));
